import{_ as a,o,c as r,a3 as s}from"./chunks/framework.BFeCKmyl.js";const u=JSON.parse('{"title":"Lembrar lei de regência da RPV por devedor","description":"","frontmatter":{"title":"Lembrar lei de regência da RPV por devedor","id":"rupe-rpv-lei-devedor","plataforma":"RUPE","grupo":"RUPE","plano":"free","desde":"1.10.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/rupe-rpv-lei-devedor"}]]},"headers":[],"relativePath":"funcionalidades/rupe-rpv-lei-devedor.md","filePath":"funcionalidades/rupe-rpv-lei-devedor.md"}'),d={name:"funcionalidades/rupe-rpv-lei-devedor.md"};function i(l,e,n,p,c,t){return o(),r("div",null,e[0]||(e[0]=[s('<h1 id="lembrar-lei-de-regencia-da-rpv-por-devedor" tabindex="-1">Lembrar lei de regência da RPV por devedor <a class="header-anchor" href="#lembrar-lei-de-regencia-da-rpv-por-devedor" aria-label="Permalink to &quot;Lembrar lei de regência da RPV por devedor&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>No cadastro de RPV do RUPE, a seção &quot;Lei de Regência da Obrigação de Pequeno Valor do Devedor&quot; pede sempre os mesmos dados para o mesmo devedor: se ele possui lei própria e, se possuir, o número, o ano e a data de publicação da lei. O eploc lembra essa resposta para cada devedor e a preenche sozinho nas próximas RPVs dele.</p><p>Também lembra o <strong>Escrivão responsável</strong> e o <strong>Magistrado(a) responsável</strong> escolhidos na última RPV e os deixa pré-selecionados na próxima.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>RUPE</strong> (<code>rupe.tjmg.jus.br</code>), tela de cadastro de RPV. As leis guardadas ficam nas configurações do eploc, no card do recurso (&quot;Gerenciar leis por devedor&quot;).</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Cadastre uma RPV normalmente, preenchendo a seção da lei de regência do devedor (ou respondendo que ele não possui lei própria), e clique em <strong>Salvar</strong>.</li><li>Na próxima RPV do mesmo devedor, assim que ele for selecionado, a seção já vem preenchida. Os campos preenchidos pelo eploc ficam destacados em azul; passe o mouse sobre eles para ver de qual devedor veio a lei.</li><li>Se a lei mudou, corrija os campos e salve a RPV: o eploc passa a usar os dados novos.</li><li>Escrivão e magistrado responsáveis: escolha-os uma vez. Na próxima RPV, eles já vêm selecionados e destacados em azul. Para trocar, basta escolher outro: a nova escolha passa a valer para as seguintes.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><ul><li><strong>Pré-selecionar o escrivão e o magistrado responsáveis escolhidos na última RPV</strong> (ligada por padrão).</li></ul><p>No card, <strong>Gerenciar leis por devedor</strong> lista os devedores guardados e permite corrigir a lei de cada um ou esquecê-lo. No topo dele, dá para incluir a lei de um devedor habitual antes mesmo da primeira RPV: informe o nome, o CPF/CNPJ (opcional, mas recomendado), se ele possui lei própria e, se possuir, número, ano e data de publicação, e clique em <strong>Incluir</strong>.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>O devedor é reconhecido pelo CPF ou CNPJ. Sem documento, pelo nome.</li><li>O eploc só guarda a lei quando a RPV é salva com a seção completa (número, ano com quatro dígitos e data no formato dd/mm/aaaa), ou com a resposta de que o devedor não possui lei própria.</li><li>Campos que já tinham valor, como os de uma RPV salva antes, não são alterados. Escrivão e magistrado só são pré-selecionados quando o campo está em &quot;Selecione&quot;.</li><li>Escrivão e magistrado não dependem do devedor: vale sempre a última escolha.</li><li>Confira a seção antes de salvar, como em qualquer preenchimento automático.</li></ul>',13)]))}const v=a(d,[["render",i]]);export{u as __pageData,v as default};
